func (e *executableSchema) Exec(ctx context.Context) graphql.ResponseHandler {
	opCtx := graphql.GetOperationContext(ctx)
	ec := newExecutionContext(opCtx, e, make(chan graphql.DeferredResult))
	inputUnmarshalMap := graphql.BuildUnmarshalerMap(
		ec.unmarshalInputAccountWhereInput,
		ec.unmarshalInputAddHouseholdUserInput,
		ec.unmarshalInputBuyInvestmentInputCustom,
		ec.unmarshalInputCreateAccountInput,
		ec.unmarshalInputCreateExpenseInputCustom,
		ec.unmarshalInputCreateHouseholdCurrencyInput,
		ec.unmarshalInputCreateHouseholdInput,
		ec.unmarshalInputCreateHouseholdInputCustom,
		ec.unmarshalInputCreateIncomeInputCustom,
		ec.unmarshalInputCreateInvestmentInput,
		ec.unmarshalInputCreateInvestmentInputCustom,
		ec.unmarshalInputCreateInvestmentLotInput,
		ec.unmarshalInputCreateRecurringSubscriptionInput,
		ec.unmarshalInputCreateSnapshotInput,
		ec.unmarshalInputCreateTransactionCategoryInput,
		ec.unmarshalInputCreateTransactionEntryInput,
		ec.unmarshalInputCreateTransactionInput,
		ec.unmarshalInputCreateTransferInputCustom,
		ec.unmarshalInputHouseholdCurrencyWhereInput,
		ec.unmarshalInputHouseholdRateWhereInput,
		ec.unmarshalInputHouseholdWhereInput,
		ec.unmarshalInputInvestmentLotWhereInput,
		ec.unmarshalInputInvestmentWhereInput,
		ec.unmarshalInputMoveInvestmentInputCustom,
		ec.unmarshalInputRecurringSubscriptionWhereInput,
		ec.unmarshalInputSellInvestmentInputCustom,
		ec.unmarshalInputSnapshotEntryWhereInput,
		ec.unmarshalInputSnapshotRateWhereInput,
		ec.unmarshalInputSnapshotWhereInput,
		ec.unmarshalInputTimePeriodInput,
		ec.unmarshalInputTransactionCategoryWhereInput,
		ec.unmarshalInputTransactionEntryWhereInput,
		ec.unmarshalInputTransactionOrder,
		ec.unmarshalInputTransactionWhereInput,
		ec.unmarshalInputUpdateAccountInput,
		ec.unmarshalInputUpdateHouseholdCurrencyInput,
		ec.unmarshalInputUpdateHouseholdInput,
		ec.unmarshalInputUpdateInvestmentInput,
		ec.unmarshalInputUpdateInvestmentLotInput,
		ec.unmarshalInputUpdateRecurringSubscriptionInput,
		ec.unmarshalInputUpdateSnapshotInput,
		ec.unmarshalInputUpdateTransactionCategoryInput,
		ec.unmarshalInputUpdateTransactionEntryInput,
		ec.unmarshalInputUpdateTransactionInput,
		ec.unmarshalInputUserHouseholdWhereInput,
		ec.unmarshalInputUserKeyWhereInput,
		ec.unmarshalInputUserWhereInput,
	)
	first := true

	switch opCtx.Operation.Operation {
	case ast.Query:
		return func(ctx context.Context) *graphql.Response {
			var response graphql.Response
			var data graphql.Marshaler
			if first {
				first = false
				ctx = graphql.WithUnmarshalerMap(ctx, inputUnmarshalMap)
				data = ec._Query(ctx, opCtx.Operation.SelectionSet)
			} else {
				if atomic.LoadInt32(&ec.PendingDeferred) > 0 {
					result := <-ec.DeferredResults
					atomic.AddInt32(&ec.PendingDeferred, -1)
					data = result.Result
					response.Path = result.Path
					response.Label = result.Label
					response.Errors = result.Errors
				} else {
					return nil
				}
			}
			var buf bytes.Buffer
			data.MarshalGQL(&buf)
			response.Data = buf.Bytes()
			if atomic.LoadInt32(&ec.Deferred) > 0 {
				hasNext := atomic.LoadInt32(&ec.PendingDeferred) > 0
				response.HasNext = &hasNext
			}

			return &response
		}
	case ast.Mutation:
		return func(ctx context.Context) *graphql.Response {
			if !first {
				return nil
			}
			first = false
			ctx = graphql.WithUnmarshalerMap(ctx, inputUnmarshalMap)
			data := ec._Mutation(ctx, opCtx.Operation.SelectionSet)
			var buf bytes.Buffer
			data.MarshalGQL(&buf)

			return &graphql.Response{
				Data: buf.Bytes(),
			}
		}

	default:
		return graphql.OneShot(graphql.ErrorResponse(ctx, "unsupported GraphQL operation"))
	}
}

type executionContext struct {
	*graphql.ExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot]
}

func newExecutionContext(
	opCtx *graphql.OperationContext,
	execSchema *executableSchema,
	deferredResults chan graphql.DeferredResult,
) *executionContext {
	return &executionContext{
		ExecutionContextState: graphql.NewExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot](
			opCtx,
			(*graphql.ExecutableSchemaState[ResolverRoot, DirectiveRoot, ComplexityRoot])(execSchema),
			parsedSchema,
			deferredResults,
		),
	}
}

//go:embed "ent.graphql" "extend.graphql" "mutation.graphql" "query.graphql"
var sourcesFS embed.FS

func sourceData(filename string) string {
	data, err := sourcesFS.ReadFile(filename)
	if err != nil {
		panic(fmt.Sprintf("codegen problem: %s not available", filename))
	}
	return string(data)
}

var sources = []*ast.Source{
	{Name: "ent.graphql", Input: sourceData("ent.graphql"), BuiltIn: false},
	{Name: "extend.graphql", Input: sourceData("extend.graphql"), BuiltIn: false},
	{Name: "mutation.graphql", Input: sourceData("mutation.graphql"), BuiltIn: false},
	{Name: "query.graphql", Input: sourceData("query.graphql"), BuiltIn: false},
}
var parsedSchema = gqlparser.MustLoadSchema(sources...)

